import AppKit

/// The About panel's credits for one app bundle: one link to its bundled
/// third-party notices (`THIRD_PARTY_LICENSES.md`, generated by
/// scripts/cmux-next/generate-third-party-notices.sh), so the licenses that
/// cmux ships under (MIT credits such as t3code included) are one click from
/// About cmux.
struct AboutPanelCredits {
    let bundle: Bundle

    /// The link text.
    static var title: String {
        String(localized: "about.credits.licenses", defaultValue: "Third-Party Licenses", table: "Windows", bundle: .module)
    }

    /// The notices file inside the bundle, when it has one.
    var licensesURL: URL? {
        nil
    }

    /// Credits text with a link to the notices file; nil without the file.
    var credits: NSAttributedString? {
        nil
    }
}
